const ticket = $json.body || $json;
const notification = ticket.notification || {};
const groupId = notification.lineGroupId || ticket.lineGroupId || '';
const mentionUserIds = notification.mentionUserIds || [];
const shouldMention = Boolean(notification.shouldMention && mentionUserIds.length);

if (!groupId) {
  return [];
}

const categoryMap = {
  '訂單問題': '訂單問題',
  '商品報價': '商品問題',
  '配送安排': '配送問題',
  '帳款月結': '客服問題',
  '其他': '客服問題',
};

const category = categoryMap[ticket.topic] || ticket.topic || '客服問題';
const priorityMap = { '急件': '緊急', '今天需回覆': '高', '一般': '普通' };
const priority = priorityMap[ticket.urgency] || ticket.urgency || '普通';
const issueId = ticket.requestId || ticket.issueId || '未填';
const createdAt = ticket.createdAt ? new Date(ticket.createdAt) : new Date();
const createdAtLabel = `${String(createdAt.getMonth() + 1).padStart(2, '0')}/${String(createdAt.getDate()).padStart(2, '0')} ${String(createdAt.getHours()).padStart(2, '0')}:${String(createdAt.getMinutes()).padStart(2, '0')}`;

function text(value, options = {}) {
  return {
    type: 'text',
    text: String(value || '未填'),
    color: options.color || '#4A4A4A',
    size: options.size || 'sm',
    weight: options.weight,
    wrap: options.wrap ?? true,
    flex: options.flex,
    align: options.align,
    margin: options.margin,
  };
}

function labelValue(label, value, options = {}) {
  return {
    type: 'box',
    layout: 'vertical',
    spacing: 'xs',
    margin: options.margin || 'md',
    contents: [
      text(label, { size: 'xs', color: '#8A8A8A', weight: 'bold' }),
      text(value, { size: options.valueSize || 'sm', weight: 'bold', color: '#4A4A4A' }),
    ],
  };
}

function postbackButton(label, data, options = {}) {
  return {
    type: 'button',
    style: options.style || 'primary',
    height: 'sm',
    color: options.color || '#6F7F8F',
    margin: options.margin || 'lg',
    action: {
      type: 'postback',
      label,
      data,
      displayText: options.displayText || label,
    },
  };
}

function actionData(action, nextStatus) {
  const pairs = [
    ['source', 'line_ticket_flex'],
    ['issue_id', issueId],
    ['action', action],
    ['next_status', nextStatus],
  ];
  return pairs.map(([key, value]) => `${key}=${encodeURIComponent(value)}`).join('&');
}

const bubble = {
  type: 'bubble',
  size: 'mega',
  styles: {
    body: { backgroundColor: '#F6F4F0' },
    footer: { backgroundColor: '#FFFFFF' },
  },
  body: {
    type: 'box',
    layout: 'vertical',
    paddingAll: '20px',
    spacing: 'md',
    contents: [
      {
        type: 'box',
        layout: 'vertical',
        spacing: 'xs',
        contents: [
          text('工單已送出', { size: 'lg', weight: 'bold', color: '#3E4448' }),
          text(`新工單・${issueId}`, { size: 'xs', weight: 'bold', color: '#6F7F8F' }),
        ],
      },
      {
        type: 'box',
        layout: 'vertical',
        margin: 'lg',
        paddingAll: '14px',
        cornerRadius: '12px',
        backgroundColor: '#FFFFFF',
        borderColor: '#E0DED8',
        borderWidth: '1px',
        spacing: 'sm',
        contents: [
          labelValue('類型', category, { margin: 'none' }),
          labelValue('客戶', ticket.customerName || '未填'),
          labelValue('聯絡人', [ticket.contactPerson, ticket.phone].filter(Boolean).join(' ') || '未填'),
          ...(ticket.relatedOrderId ? [labelValue('相關訂單', ticket.relatedOrderId)] : []),
          labelValue('內容', ticket.message || '未填', { valueSize: 'md' }),
          labelValue('優先', priority),
          labelValue('建立', createdAtLabel),
          {
            type: 'separator',
            margin: 'lg',
            color: '#E8E1D8',
          },
          text('請由群組負責人點擊下���按鈕接手。', { size: 'xs', color: '#8A8A8A' }),
        ],
      },
    ],
  },
  footer: {
    type: 'box',
    layout: 'vertical',
    paddingAll: '16px',
    spacing: 'sm',
    contents: [
      postbackButton('我收到工單', actionData('accept', '已受理'), {
        color: '#6F7F8F',
        displayText: '我收到工單',
      }),
    ],
  },
};

const messages = [];

if (shouldMention) {
  const substitution = {};
  const mentionTokens = mentionUserIds.map((userId, index) => {
    const key = `u${index + 1}`;
    substitution[key] = { type: 'mention', mentionee: { type: 'user', userId } };
    return `{${key}}`;
  });

  messages.push({
    type: 'textV2',
    text: `${mentionTokens.join(' ')}\n有一張急件工單需要協助：${issueId}`,
    substitution,
  });
}

messages.push({
  type: 'flex',
  altText: `新工單 ${issueId} ${category}`,
  contents: bubble,
});

return [{
  json: {
    to: groupId,
    messages,
  },
}];
